"use client";

import * as React from "react";
import { Avatar as AvatarPrimitive } from "@base-ui/react/avatar";

import { cn } from "@/lib/utils";
import { softPanel } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Mallow Avatar: a 2.5rem round photo set on the chosen-option tint inside a violet ring. */
const Avatar = React.forwardRef<HTMLSpanElement, WithClassName<AvatarPrimitive.Root.Props>>(
  ({ className, ...props }, ref) => (
    <AvatarPrimitive.Root
      ref={ref}
      data-slot="avatar"
      className={cn(
        "relative flex size-10 shrink-0 select-none overflow-hidden rounded-full",
        softPanel,
        className,
      )}
      {...props}
    />
  ),
);
Avatar.displayName = "Avatar";

/** The photo, cropped to fill the circle. */
const AvatarImage = React.forwardRef<HTMLImageElement, WithClassName<AvatarPrimitive.Image.Props>>(
  ({ className, ...props }, ref) => (
    <AvatarPrimitive.Image
      ref={ref}
      data-slot="avatar-image"
      className={cn("aspect-square size-full object-cover", className)}
      {...props}
    />
  ),
);
AvatarImage.displayName = "AvatarImage";

/** Initials on the light violet tint, shown while the photo loads or when it fails. */
const AvatarFallback = React.forwardRef<HTMLSpanElement, WithClassName<AvatarPrimitive.Fallback.Props>>(
  ({ className, ...props }, ref) => (
    <AvatarPrimitive.Fallback
      ref={ref}
      data-slot="avatar-fallback"
      className={cn(
        "flex size-full items-center justify-center rounded-full text-sm font-medium text-foreground",
        className,
      )}
      {...props}
    />
  ),
);
AvatarFallback.displayName = "AvatarFallback";

export { Avatar, AvatarImage, AvatarFallback };
